curl -s -o /dev/null -w "dev_server_now=%{http_code}\n" http://localhost:3000/; cat > /tmp/serve.js <<'EOF'
const http=require('http'),fs=require('fs'),path=require('path');
const root='/workspace/out';
http.createServer((req,res)=>{let p=decodeURIComponent(req.url.split('?')[0]);if(p==='/')p='/index.html';
let f=path.join(root,p);if(!f.startsWith(root)){res.writeHead(403);res.end();return;}
fs.readFile(f,(e,d)=>{if(e){fs.readFile(f+'/index.html',(e2,d2)=>{if(e2){res.writeHead(404);res.end(fs.existsSync(path.join(root,'404.html'))?fs.readFileSync(path.join(root,'404.html')):'nf');}else{res.writeHead(200,{'Content-Type':'text/html'});res.end(d2);}});}else{res.writeHead(200,{'Content-Type':f.endsWith('.html')?'text/html':'application/octet-stream'});res.end(d);}});}).listen(8080,()=>console.log('up'));
EOF
nohup node /tmp/serve.js > /tmp/static.log 2>&1 & sleep 2; for p in / /ea-repository /technologie-radar /nonexistent-xyz; do code=$(curl -s -o /tmp/sp.html -w "%{http_code}" "http://localhost:8080$p"); echo "$code  out$p"; done; grep -oP '(?<=<title>)[^<]+' /tmp/sp.html | head -1; curl -s http://localhost:8080/ | grep -oP '(?<=<title>)[^<]+'
